    const render=()=>{const l=LANGS[sel.value]||LANGS.en;button.innerHTML=`<img class="lang-flag-img" src="${l.flagUrl}" alt=""><i class="fa-solid fa-chevron-down"></i>`;button.setAttribute('aria-label',l.code);menu.innerHTML=Object.entries(LANGS).map(([k,v])=>`<button type="button" class="lang-choice ${k===sel.value?'active':''}" data-lang="${k}" aria-label="${v.code}"><img class="lang-flag-img" src="${v.flagUrl}" alt="${v.code}"></button>`).join('')};
