    const fields=[['filterGeneration','generation'],['filterTrim','trim'],['filterMarketOrigin','origin'],['filterDistrict','district']];fields.forEach(([id,k])=>{const e=$('#'+id)||document.querySelector(`[name="${id.replace('filter','').replace(/^./,x=>x.toLowerCase())}"]`);if(e)e.placeholder=L()[k]});
    $$('input[placeholder],textarea[placeholder]').forEach(e=>{let x=e.placeholder;x=x.replace(/^Məs:\s*/i,lang()==='ru'?'Напр.: ':lang()==='en'?'e.g. ':lang()==='tr'?'Örn: ':lang()==='ka'?'მაგ: ':'Məs: ');e.placeholder=x});
