  async function toggleNotifications(){
    document.querySelectorAll('.lang-picker-menu').forEach(x=>x.hidden=true);document.documentElement.classList.remove('popover-open');
    let pop=$('#notificationPopover');if(pop){pop.remove();document.documentElement.classList.remove('popover-open');return}pop=document.createElement('div');pop.id='notificationPopover';pop.className='notification-popover';pop.innerHTML=`<div class="notification-head"><strong>${L().notifications}</strong><button type="button" id="markAllRead">${L().markAll}</button></div><div class="notification-list"><div class="muted small">...</div></div>`;document.body.append(pop);document.documentElement.classList.add('popover-open');
    const btn=$('#notificationBtn'),r=btn.getBoundingClientRect(),margin=8,width=Math.min(380,innerWidth-margin*2);pop.style.width=`${width}px`;pop.style.top=`${Math.min(innerHeight-120,r.bottom+8)}px`;pop.style.left=`${Math.max(margin,Math.min(innerWidth-width-margin,r.right-width))}px`;
    const root=pop.querySelector('.notification-list');if(!me){root.innerHTML=`<div class="empty-notice">${L().noNotifications}</div>`;return}
    const {data,error}=await sb.from('notifications').select('*').eq('user_id',me.id).order('created_at',{ascending:false}).limit(30);if(error){root.textContent=error.message;return}const rows=data||[],ids=[...new Set(rows.map(x=>x.actor_id).filter(Boolean))],actors={};if(ids.length){const {data:u}=await sb.from('users').select('id,name,surname,avatar_url').in('id',ids);(u||[]).forEach(x=>actors[x.id]=x)}
    root.innerHTML=rows.length?rows.map(n=>{const a=actors[n.actor_id]||{},name=[a.name,a.surname].filter(Boolean).join(' ')||L().user;return `<a class="notification-row ${n.is_read?'':'unread'}" href="${esc(n.url||'#')}"><img class="notification-avatar" src="${esc(a.avatar_url||'assets/img/brand/icon-192.png')}" alt=""><div><p><strong>${esc(name)}</strong> ${esc(notificationText(n))}</p><small>${new Date(n.created_at).toLocaleString()}</small></div></a>`}).join(''):`<div class="empty-notice">${L().noNotifications}</div>`;
    pop.querySelector('#markAllRead').onclick=async()=>{await sb.from('notifications').update({is_read:true}).eq('user_id',me.id).eq('is_read',false);pop.remove();document.documentElement.classList.remove('popover-open');updateNotificationBadge()};
    setTimeout(()=>document.addEventListener('click',function close(e){if(!pop.isConnected){document.removeEventListener('click',close,true);return}if(!pop.contains(e.target)&&!btn.contains(e.target)){pop.remove();document.documentElement.classList.remove('popover-open');document.removeEventListener('click',close,true)}},true),0);
  }
  function setupDraftPersistence(){
    const page=document.body.dataset.page;
    if(page==='home')persistFields('avtovip-filter-draft-v2',['filterBrand','filterModel','filterCountry','filterCountryAdvanced','filterState','filterCity','filterCityAdvanced','filterDistrict','filterPriceMin','filterPriceMax','filterCurrency','filterYearMin','filterYearMax','filterCondition','filterMileageMin','filterMileageMax','filterEngineMin','filterEngineMax','filterPowerMin','filterPowerMax','filterFuel','filterTransmission','filterDrivetrain','filterBody','filterColor','filterSeatsMin','filterSeatsMax','filterOwnersMax','filterGeneration','filterTrim','filterMarketOrigin','filterVin','filterCredit','filterBarter','filterDamage','filterPainted','sortListings','vipOnly'],true);
    if(page==='create-listing')persistForm('listingForm','avtovip-listing-draft-v2');
  }
  function persistFields(key,ids,trigger=false){
    let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')}catch{}
    const restore=()=>{for(const id of ids){const e=document.getElementById(id);if(!e||saved[id]===undefined)continue;if(e.type==='checkbox')e.checked=!!saved[id];else if(e.tagName==='BUTTON')e.dataset.on=saved[id];else if([...e.options||[]].some(o=>o.value===saved[id])||e.tagName!=='SELECT')e.value=saved[id]}if(trigger)document.getElementById('filterBrand')?.dispatchEvent(new Event('change',{bubbles:true}))};
    setTimeout(restore,900);setTimeout(restore,1800);
    const save=()=>{const x={};for(const id of ids){const e=document.getElementById(id);if(!e)continue;x[id]=e.type==='checkbox'?e.checked:e.tagName==='BUTTON'?e.dataset.on:e.value}localStorage.setItem(key,JSON.stringify(x))};document.addEventListener('input',e=>{if(ids.includes(e.target.id))save()});document.addEventListener('change',e=>{if(ids.includes(e.target.id))save()});
    $('#resetFilters')?.addEventListener('click',()=>localStorage.removeItem(key));
  }
  function persistForm(id,key){
    const form=document.getElementById(id);if(!form)return;let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')}catch{}
    const restore=()=>{for(const [name,v] of Object.entries(saved)){const nodes=[...form.querySelectorAll(`[name="${CSS.escape(name)}"]`)];if(!nodes.length)continue;if(nodes[0].type==='checkbox'){nodes.forEach(n=>n.checked=Array.isArray(v)?v.includes(n.value):!!v)}else if(nodes[0].type==='radio'){nodes.forEach(n=>n.checked=n.value===v)}else if(nodes[0].type!=='file'){const n=nodes[0];if(n.tagName!=='SELECT'||[...n.options].some(o=>o.value===v))n.value=v}}};setTimeout(restore,1000);setTimeout(restore,2200);
    const save=()=>{const out={};const fd=new FormData(form);for(const e of form.elements){if(!e.name||e.type==='file')continue;if(e.type==='checkbox'){out[e.name]=[...form.querySelectorAll(`[name="${CSS.escape(e.name)}"]:checked`)].map(x=>x.value)}else if(e.type==='radio'){if(e.checked)out[e.name]=e.value}else out[e.name]=e.value}localStorage.setItem(key,JSON.stringify(out))};form.addEventListener('input',save);form.addEventListener('change',save);
    const note=document.createElement('div');note.className='draft-note';note.innerHTML=`<i class="fa-solid fa-cloud-arrow-down"></i> ${L().draft}`;form.prepend(note);
  }

  function normalizeSearchTerm(v){return String(v||'').trim().replace(/[(),%]/g,' ').replace(/\s+/g,' ').slice(0,80)}
  function foldSearch(v){return normalizeSearchTerm(v).toLocaleLowerCase('az').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ə/g,'e').replace(/ı/g,'i').replace(/ö/g,'o').replace(/ü/g,'u').replace(/ğ/g,'g').replace(/ş/g,'s').replace(/ç/g,'c')}
