  function userResultCard(u){const name=[u.name,u.surname].filter(Boolean).join(' ')||L().user;return `<a class="explore-user-result" href="user.html?id=${u.id}"><img src="${esc(u.avatar_url||'assets/img/brand/icon-192.png')}" alt=""><div><strong>${verifiedIcon(u)}<span>${esc(name)}</span></strong><span>${esc([u.city,u.address].filter(Boolean).join(' · '))}</span></div><i class="fa-solid fa-chevron-right"></i></a>`}
