  function initExploreSearch(){
    const input=$('#exploreSearch'),out=$('#exploreSearchResults'),feed=$('#exploreFeed'),clear=$('#exploreSearchClear');if(!input||!out)return;
    let timer=0,seq=0;
    const reset=()=>{input.value='';clear.hidden=true;out.hidden=true;out.innerHTML='';feed.hidden=false};
    clear.onclick=reset;
    if(out.dataset.actionsBound!=='1'){out.dataset.actionsBound='1';out.addEventListener('click',exploreAction)}
    input.addEventListener('input',()=>{
      clear.hidden=!input.value;clearTimeout(timer);const q=normalizeSearchTerm(input.value);
      if(q.length<2){out.hidden=true;out.innerHTML='';feed.hidden=false;return}
      timer=setTimeout(async()=>{
        const current=++seq;feed.hidden=true;out.hidden=false;out.innerHTML='<div class="explore-search-loading"><i class="fa-solid fa-spinner fa-spin"></i></div>';
        const like=`%${q}%`,qFold=foldSearch(q);
        const usersRes=await sb.from('users').select('id,name,surname,avatar_url,whatsapp_phone,phone,trust_score,membership_tier,is_verified,city,address').limit(500);
        if(current!==seq)return;
        const matchedUsers=(usersRes.data||[]).filter(u=>foldSearch([u.name,u.surname].filter(Boolean).join(' ')).includes(qFold)).slice(0,24);
        const userIds=matchedUsers.map(u=>u.id);
        const fields='id,user_id,brand,model,generation,trim,year,city,state_name,district,country_code,price,currency,image_urls,is_vip,is_premium,mileage,engine_volume,fuel,transmission,description,body_type,color,market_origin,vin,created_at';
        const listingQuery=sb.from('elanlar').select(fields).eq('status','approved').or(`brand.ilike.${like},model.ilike.${like},generation.ilike.${like},trim.ilike.${like},city.ilike.${like},state_name.ilike.${like},district.ilike.${like},description.ilike.${like},body_type.ilike.${like},fuel.ilike.${like},transmission.ilike.${like},color.ilike.${like},market_origin.ilike.${like},vin.ilike.${like}`).order('is_premium',{ascending:false}).order('is_vip',{ascending:false}).limit(48);
        const tasks=[listingQuery];
        if(/^\d{4}$/.test(q))tasks.push(sb.from('elanlar').select(fields).eq('status','approved').eq('year',Number(q)).order('is_premium',{ascending:false}).order('is_vip',{ascending:false}).limit(48));
        if(userIds.length)tasks.push(sb.from('elanlar').select(fields).eq('status','approved').in('user_id',userIds).order('is_premium',{ascending:false}).order('is_vip',{ascending:false}).limit(48));
        const results=await Promise.all(tasks);if(current!==seq)return;
        const merged=new Map();for(const r of results)for(const x of (r.data||[]))merged.set(x.id,x);
        let list=[...merged.values()];
        const uids=[...new Set(list.map(x=>x.user_id).filter(Boolean))],profiles={};
        for(const u of matchedUsers)profiles[u.id]=u;
        if(uids.some(id=>!profiles[id])){const {data:p}=await sb.from('users').select('id,name,surname,avatar_url,whatsapp_phone,phone,trust_score,membership_tier,is_verified,city,address').in('id',uids);(p||[]).forEach(x=>profiles[x.id]=x)}
        const ids=list.map(x=>x.id);let likes=[],comments=[];
        if(ids.length){const [lr,cr]=await Promise.all([sb.from('listing_likes').select('listing_id,user_id').in('listing_id',ids),sb.from('listing_comments').select('listing_id,id').in('listing_id',ids)]);likes=lr.data||[];comments=cr.data||[]}
        const myLikes=new Set(likes.filter(x=>x.user_id===me?.id).map(x=>x.listing_id));
        const people=matchedUsers.length?`<div class="explore-user-results">${matchedUsers.map(userResultCard).join('')}</div>`:'';
        const cards=list.length?`<div class="explore-feed explore-search-feed">${list.map(x=>exploreCard(x,profiles[x.user_id]||{},likes.filter(y=>y.listing_id===x.id).length,comments.filter(y=>y.listing_id===x.id).length,myLikes.has(x.id))).join('')}</div>`:'';
        out.innerHTML=(people||cards)?`${people}${cards}`:`<div class="empty-state">${L().noSearch}</div>`;
        initExploreSlides(out);
      },180)
    });
  }
  async function initExplore(){
    const feed=$('#exploreFeed');if(!feed)return;await auth();let offset=0,busy=false,done=false;const limit=16;let blocked=new Set();if(me){const [blocksRes,followsRes]=await Promise.all([sb.from('user_blocks').select('blocked_id').eq('blocker_id',me.id),sb.from('user_follows').select('following_id').eq('follower_id',me.id)]);blocked=new Set((blocksRes.data||[]).map(x=>x.blocked_id));exploreFollowing=new Set((followsRes.data||[]).map(x=>x.following_id))}else exploreFollowing=new Set();initExploreSearch();
    async function more(){if(busy||done)return;busy=true;$('#exploreLoader').hidden=false;let q=sb.from('elanlar').select('*').eq('status','approved').order('is_premium',{ascending:false}).order('is_vip',{ascending:false}).order('created_at',{ascending:false}).range(offset,offset+limit-1);const {data,error}=await q;if(error){feed.insertAdjacentHTML('beforeend',`<div class="empty-state">${esc(error.message)}</div>`);busy=false;return}offset+=limit;if((data||[]).length<limit)done=true;const rows=(data||[]).filter(x=>!blocked.has(x.user_id));rows.sort((a,b)=>(b.is_premium-a.is_premium)||(b.is_vip-a.is_vip)||(Math.random()-.5));const ids=rows.map(x=>x.id),uids=[...new Set(rows.map(x=>x.user_id))];let profiles={},likes=[],comments=[];if(uids.length){const {data:p}=await sb.from('users').select('id,name,surname,avatar_url,whatsapp_phone,phone,trust_score,membership_tier,is_verified,city,address').in('id',uids);(p||[]).forEach(x=>profiles[x.id]=x)}if(ids.length){const [lr,cr]=await Promise.all([sb.from('listing_likes').select('listing_id,user_id').in('listing_id',ids),sb.from('listing_comments').select('listing_id,id').in('listing_id',ids)]);likes=lr.data||[];comments=cr.data||[]}
      const myLikes=new Set(likes.filter(x=>x.user_id===me?.id).map(x=>x.listing_id));feed.insertAdjacentHTML('beforeend',rows.map(x=>exploreCard(x,profiles[x.user_id]||{},likes.filter(y=>y.listing_id===x.id).length,comments.filter(y=>y.listing_id===x.id).length,myLikes.has(x.id))).join(''));initExploreSlides(feed);$('#exploreLoader').hidden=true;busy=false;if(!rows.length&&done&&!feed.children.length)feed.innerHTML=`<div class="empty-state">${L().noExplore}</div>`}
    const io=new IntersectionObserver(es=>{if(es.some(x=>x.isIntersecting))more()},{rootMargin:'500px'});io.observe($('#exploreSentinel'));feed.addEventListener('click',exploreAction);await more();
  }
