      const next=()=>{if(busy||!box.isConnected||document.hidden)return;busy=true;const ni=(i+1)%images.length;const preload=new Image();preload.onload=()=>{img.classList.add('is-changing');setTimeout(()=>{img.src=images[ni];i=ni;requestAnimationFrame(()=>img.classList.remove('is-changing'));busy=false},150)};preload.onerror=()=>{i=ni;busy=false};preload.src=images[ni]};
